200:function adjustDueDate(rating: ReviewRating): string {
201:  const now = new Date();
202:
203:  switch (rating) {
204:    case 'again':
205:      now.setHours(now.getHours() + 2);
206:      break;
207:    case 'hard':
208:      now.setDate(now.getDate() + 1);
209:      break;
210:    case 'good':
211:      now.setDate(now.getDate() + 3);
212:      break;
213:    case 'easy':
214:      now.setDate(now.getDate() + 7);
215:      break;
216:  }
217:
218:  return now.toISOString();
219:}
