221:function getFlashcardStateForRating(rating: ReviewRating): FlashcardState {
222:  switch (rating) {
223:    case 'again':
224:    case 'hard':
225:      return 'learning';
226:    case 'good':
227:      return 'reviewing';
228:    case 'easy':
229:      return 'mastered';
230:  }
231:}
