233:export function recordFlashcardReview(
234:  progress: UserProgress,
235:  moduleId: string,
236:  cardId: string,
237:  rating: ReviewRating
238:): UserProgress {
239:  const moduleProgress = progress.modules[moduleId] ?? {
240:    sectionsRead: {},
241:    flashcards: {}
242:  };
243:  const existing = moduleProgress.flashcards[cardId] ?? {
244:    state: 'new',
245:    reviewCount: 0,
246:    dueDateIso: new Date().toISOString()
247:  };
248:  const updatedFlashcards = {
249:    ...moduleProgress.flashcards,
250:    [cardId]: {
251:      state: getFlashcardStateForRating(rating),
252:      reviewCount: existing.reviewCount + 1,
253:      dueDateIso: adjustDueDate(rating)
254:    }
255:  };
256:
257:  return {
258:    ...progress,
259:    modules: {
260:      ...progress.modules,
261:      [moduleId]: {
262:        ...moduleProgress,
263:        flashcards: updatedFlashcards
264:      }
265:    }
266:  };
267:}
